        () async {
      applePlatform.credential = const AuthorizationCredentialAppleID(
        userIdentifier: 'a-1',
        givenName: null,
        familyName: null,
        email: null,
        authorizationCode: 'code',
        identityToken: 'jwt',
        state: null,
      );

      final AppUser? user = await service.signInWithApple();

      expect(user!.displayName, isNull);
      expect(user.email, isNull);
      expect(user.id, 'a-1');
