  ///
  /// If a foreground color is not specified, the theme's text color is used.
  final Color? foregroundColor;

  /// The color with which to fill the circle. Changing the background color
  /// will cause the avatar to animate to the new color.
  ///
  /// If a background color is not specified, the theme's primary color is used.
  final Color? backgroundColor;

  /// The URL of a photo to use if the user's [identity] does not specify a
  /// `photoUrl`.
  ///
  /// If this is `null` and the user's [identity] does not contain a photo URL,
  /// then this widget will attempt to display the user's first initial as
  /// determined from the identity's [displayName] field. If that is `null` a
  /// default (generic) Google profile photo will be displayed.
  final String? placeholderPhotoUrl;

  @override
  Widget build(BuildContext context) {
    return CircleAvatar(
      backgroundColor: backgroundColor,
      foregroundColor: foregroundColor,
      child: LayoutBuilder(builder: _buildClippedImage),
    );
  }

  Widget _buildClippedImage(BuildContext context, BoxConstraints constraints) {
    assert(constraints.maxWidth == constraints.maxHeight);

    // Placeholder to use when there is no photo URL, and while the photo is
    // loading. Uses the first character of the display name (if it has one),
    // or the first letter of the email address if it does not.
    final List<String?> placeholderCharSources = <String?>[
      identity.displayName,
      identity.email,
      '-',
    ];
    final String placeholderChar =
        placeholderCharSources
            .firstWhere(
              (String? str) => str != null && str.trimLeft().isNotEmpty,
            )!
            .trimLeft()[0]
            .toUpperCase();
    final Widget placeholder = Center(
      child: Text(placeholderChar, textAlign: TextAlign.center),
    );

    final String? photoUrl = identity.photoUrl ?? placeholderPhotoUrl;
    if (photoUrl == null) {
      return placeholder;
    }

    // Add a sizing directive to the profile photo URL.
    final double size =
        MediaQuery.of(context).devicePixelRatio * constraints.maxWidth;
    final String sizedPhotoUrl = fife.addSizeDirectiveToUrl(photoUrl, size);

    // Fade the photo in over the top of the placeholder.
    return SizedBox(
      width: size,
      height: size,
      child: ClipOval(
        child: Stack(
          fit: StackFit.expand,
          children: <Widget>[
            placeholder,
            FadeInImage.memoryNetwork(
              // This creates a transparent placeholder image, so that
              // [placeholder] shows through.
              placeholder: _transparentImage,
              image: sizedPhotoUrl,
            ),
          ],
        ),
      ),
    );
  }
}

/// This is an transparent 1x1 gif image.
///
/// Those bytes come from `resources/transparentImage.gif`.
final Uint8List _transparentImage = Uint8List.fromList(<int>[
  0x47, 0x49, 0x46, 0x38, 0x39, 0x61, 0x01, 0x00, 0x01, 0x00, 0x80, 0x00, //
  0x00, 0x00, 0x00, 0x00, 0xFF, 0xFF, 0xFF, 0x21, 0xf9, 0x04, 0x01, 0x00, //
  0x00, 0x00, 0x00, 0x2C, 0x00, 0x00, 0x00, 0x00, 0x01, 0x00, 0x01, 0x00, //
  0x00, 0x02, 0x01, 0x44, 0x00, 0x3B,
]);

{"content":"import 'package:dm_tools_app_example/domain/app_user.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  group('AppUser', () {
    const googleUser = AppUser(
      id: 'google-1',
      provider: AuthProvider.google,
      displayName: 'Jane Doe',
      email: 'jane@example.com',
    );
    const appleUser = AppUser(
      id: 'apple-1',
      provider: AuthProvider.apple,
      displayName: 'John Roe',
      email: 'john@privaterelay.appleid.com',
    );

    test('toJson/fromJson roundtrips a Google user', () {
      final AppUser restored = AppUser.fromJson(googleUser.toJson());

      expect(restored, equals(googleUser));
      expect(restored.id, 'google-1');
      expect(restored.provider, AuthProvider.google);
      expect(restored.displayName, 'Jane Doe');
      expect(restored.email, 'jane@example.com');
    });

    test('toJson/fromJson roundtrips an Apple user', () {
      final AppUser restored = AppUser.fromJson(appleUser.toJson());

      expect(restored, equals(appleUser));
      expect(restored.provider, AuthProvider.apple);
    });

    test('toJson/fromJson roundtrips nullable profile fields', () {
      // Apple only returns name/email on the first authorization; later
      // credentials carry just the user identifier.
      const anonymousAppleUser = AppUser(id: 'apple-2', provider: AuthProvider.apple);

      final AppUser restored = AppUser.fromJson(anonymousAppleUser.toJson());

      expect(restored, equals(anonymousAppleUser));
      expect(restored.displayName, isNull);
      expect(restored.email, isNull);
    });

    test('fromJson throws for an unknown provider', () {
      expect(
        () => AppUser.fromJson(<String, dynamic>{
          'id': 'x',
          'provider': 'microsoft',
        }),
        throwsArgumentError,
      );
    });

    test('users with different ids or providers are not equal', () {
      expect(googleUser, isNot(equals(appleUser)));
      expect(
        googleUser,
        isNot(equals(const AppUser(id: 'google-2', provider: AuthProvider.google))),
      );
      expect(googleUser, equals(googleUser));
    });

    test('copyWith replaces only the given fields', () {
      final AppUser updated = googleUser.copyWith(displayName: 'Jane Roe');

      expect(updated.displayName, 'Jane Roe');
      expect(updated.id, googleUser.id);
      expect(updated.provider, googleUser.provider);
      expect(updated.email, googleUser.email);
    });
  });
}
