{"content":"import 'dart:convert';

import 'package:dm_tools_app_example/domain/app_user.dart';
import 'package:shared_preferences/shared_preferences.dart';

/// Persists the account to remember between app launches.
///
/// The store holds at most one remembered account: [save] replaces any
/// previous one and [clear] forgets it entirely (sign-out).
abstract class SessionStore {
  /// Remembers [user] across app restarts.
  Future<void> save(AppUser user);

  /// Returns the remembered account, or `null` when none was saved.
  Future<AppUser?> load();

  /// Forgets the remembered account, if any.
  Future<void> clear();
}

/// [SessionStore] backed by `shared_preferences` (local device storage).
class SharedPreferencesSessionStore implements SessionStore {
  /// Creates a store. Tests may inject a [prefs] instance with mock
  /// initial values; production resolves the real one lazily.
  SharedPreferencesSessionStore({SharedPreferences? prefs})
      : _prefsOverride = prefs;

  final SharedPreferences? _prefsOverride;
  SharedPreferences? _prefsCache;

  static const String _storageKey = 'remembered_account';

  Future<SharedPreferences> _prefs() async {
    return _prefsOverride ??= await SharedPreferences.getInstance();
  }

  @override
  Future<void> save(AppUser user) async {
    final SharedPreferences prefs = await _prefs();
    await prefs.setString(_storageKey, jsonEncode(user.toJson()));
  }

  @override
  Future<AppUser?> load() async {
    final SharedPreferences prefs = await _prefs();
    final String? raw = prefs.getString(_storageKey);
    if (raw == null) {
      return null;
    }
    return AppUser.fromJson(
      jsonDecode(raw) as Map<String, dynamic>,
    );
  }

  @override
  Future<void> clear() async {
    final SharedPreferences prefs = await _prefs();
    await prefs.remove(_storageKey);
  }
}

/// In-memory [SessionStore] for tests and previews; nothing survives the
/// process lifetime.
class InMemorySessionStore implements SessionStore {
  AppUser? _user;

  @override
  Future<void> save(AppUser user) async {
    _user = user;
  }

  @override
  Future<AppUser?> load() async {
    return _user;
  }

  @override
  Future<void> clear() async {
    _user = null;
  }
}
","path":"lib/services/session_store.dart"}

{"content":"import 'package:dm_tools_app_example/domain/app_user.dart';
import 'package:google_sign_in/google_sign_in.dart';
import 'package:sign_in_with_apple/sign_in_with_apple.dart';

/// Signs users in through the social providers and signs them out.
///
/// Cancellation is reported as `null` (not an exception): the caller can
/// distinguish "user backed out" from "the flow failed".
abstract class AuthService {
  /// Runs the Google sign-in flow. Returns the account, or `null` when the
  /// user canceled.
  Future<AppUser?> signInWithGoogle();

  /// Runs the Apple sign-in flow. Returns the account, or `null` when the
  /// user canceled.
  Future<AppUser?> signInWithApple();

  /// Signs the user out of the active provider session.
  Future<void> signOut();
}

/// Real [AuthService] backed by the `google_sign_in` and
/// `sign_in_with_apple` plugins.
class GoogleAppleAuthService implements AuthService {
  /// Creates the service. Tests may inject a [googleSignIn] instance.
  GoogleAppleAuthService({GoogleSignIn? googleSignIn})
      : _googleSignInOverride = googleSignIn;

  final GoogleSignIn? _googleSignInOverride;
  GoogleSignIn? _googleSignIn;
  bool _googleInitialized = false;

  GoogleSignIn get _google =>
      _googleSignInOverride ?? _googleSignIn ??= GoogleSignIn.instance;

  @override
  Future<AppUser?> signInWithGoogle() async {
    // GoogleSignIn 7.x requires a single initialize() before authenticate().
    if (!_googleInitialized) {
      await _google.initialize();
      _googleInitialized = true;
    }

    try {
      final GoogleSignInAccount account = await _google.authenticate(
        scopeHint: const <String>['email'],
      );
      return AppUser(
        id: account.id,
        provider: AuthProvider.google,
        displayName: account.displayName,
        email: account.email,
      );
    } on GoogleSignInException catch (exception) {
      if (exception.code == GoogleSignInExceptionCode.canceled) {
        return null;
      }
      rethrow;
    }
  }

  @override
  Future<AppUser?> signInWithApple() async {
    try {
      final AuthorizationCredentialAppleID credential =
          await SignInWithApple.getAppleIDCredential(
        scopes: <AppleIDAuthorizationScopes>[
          AppleIDAuthorizationScopes.fullName,
          AppleIDAuthorizationScopes.email,
        ],
      );

      final String? displayName = <String?>[
        credential.givenName,
        credential.familyName,
      ]
          .whereType<String>()
          .map((String part) => part.trim())
          .where((String part) => part.isNotEmpty)
          .join(' ');

      return AppUser(
        // iOS always reports a userIdentifier; on other platforms fall
        // back to the identity token so the account is still addressable.
        id: credential.userIdentifier ??
            credential.identityToken ??
            'apple-unknown',
        provider: AuthProvider.apple,
        displayName: displayName.isEmpty ? null : displayName,
        email: credential.email,
      );
    } on SignInWithAppleAuthorizationException catch (exception) {
      if (exception.code == AuthorizationErrorCode.canceled) {
        return null;
      }
      rethrow;
    }
  }

  @override
  Future<void> signOut() async {
    // Calling signOut() before initialize() throws on the real SDK, and
    // only Google keeps a plugin-side session.
    if (_googleInitialized || _googleSignInOverride != null) {
      await _google.signOut();
    }
  }
}
